  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills tiles with water up to the specified distance from the source using BFS.
   * Algorithm:
   *   1. If distance == 0, return.
   *   2. If this is the first fill (prevFilledDistance is null or distance > prevFilledDistance):
   *      a. Perform BFS from the source cell, expanding outward through connected pipes.
   *      b. For each reachable pipe cell within the given distance, mark it as filled.
   *      c. Update filledTiles list with newly filled coordinates.
   *      d. Update prevFilledDistance to current distance.
   *      e. Update prevFilledTiles count.
   *   3. Otherwise, if distance <= prevFilledDistance, do nothing (already filled to that distance).
   * Related Features: sourceCell, filledTiles, prevFilledDistance, prevFilledTiles fields
   * Related Classes: TerminationCell, Coordinate, Pipe, Direction
   * Input: distance : int - the maximum distance to fill from source
   * Output: void
   * Pre-condition: distance >= 0
   * Post-condition: All reachable pipe cells within the specified distance from source are marked as filled.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance == 0) {
      return;
    }
    if (getPrevFilledDistance() == null || distance > getPrevFilledDistance()) {
      // BFS from source cell
      Queue<Coordinate> queue = new LinkedList<Coordinate>();
      boolean[][] visited = new boolean[getRows()][getCols()];
      
      Coordinate sourceCoord = getSourceCell().getCoord();
      queue.add(sourceCoord);
      visited[sourceCoord.getRow()][sourceCoord.getCol()] = true;
      
      int[][] dist = new int[getRows()][getCols()];
      dist[sourceCoord.getRow()][sourceCoord.getCol()] = 0;
      
      EList<Coordinate> newFilledTiles = new BasicEList<Coordinate>();
      
      Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
      
      while (!queue.isEmpty()) {
        Coordinate current = queue.poll();
        int currentDist = dist[current.getRow()][current.getCol()];
        
        if (currentDist > 0) {
          // Mark the cell as filled if it has a pipe
          Cell cellAt = getCell()[current.getRow()][current.getCol()];
          if (cellAt instanceof FillableCell) {
            FillableCell fc = (FillableCell) cellAt;
            if (fc.getPipe() != null) {
              fc.getPipe().setFilled(true);
              newFilledTiles.add(current);
            }
          } else if (cellAt instanceof TerminationCell) {
            TerminationCell tc = (TerminationCell) cellAt;
            tc.setFilled(true);
            if (tc.getType() == TerminationType.SINK) {
              newFilledTiles.add(current);
            }
          }
        }
        
        if (currentDist >= distance) {
          continue;
        }
        
        // Get the pipe at current cell to find connections
        Cell cellAt = getCell()[current.getRow()][current.getCol()];
        EList<Direction> connections = null;
        
        if (cellAt instanceof FillableCell) {
          FillableCell fc = (FillableCell) cellAt;
          if (fc.getPipe() != null) {
            connections = fc.getPipe().getConnections();
          }
        } else if (cellAt instanceof TerminationCell) {
          TerminationCell tc = (TerminationCell) cellAt;
          // Use the pointingTo direction as the connection
          connections = new BasicEList<Direction>();
          connections.add(tc.getPointingTo());
        }
        
        if (connections != null) {
          for (Direction dir : connections) {
            Coordinate offset = helper.getOffset(dir);
            Coordinate neighbor = current.add(offset);
            int nr = neighbor.getRow();
            int nc = neighbor.getCol();
            
            if (nr >= 0 && nr < getRows() && nc >= 0 && nc < getCols() && !visited[nr][nc]) {
              visited[nr][nc] = true;
              dist[nr][nc] = currentDist + 1;
              queue.add(neighbor);
            }
          }
        }
      }
      
      // Update filledTiles list
      getFilledTiles().clear();
      getFilledTiles().addAll(newFilledTiles);
      
      // Update prevFilledDistance
      prevFilledDistance = distance;
      
      // Update prevFilledTiles count
      prevFilledTiles = newFilledTiles.size();
    }
  }

